const adtOperationText = (value: string, locale: Locale) => {
  if (locale !== "vi") return value;
  const notes: Record<string, string> = {
    "PUSH(7)": "PUSH(7) · thêm 7 vào đỉnh", "ENQUEUE(7)": "ENQUEUE(7) · thêm 7 vào cuối", "ENQUEUE(A), ENQUEUE(B), DEQUEUE()": "thêm A, thêm B, rồi lấy phần tử đầu", "INSERT_AFTER(30, 40)": "chèn 40 sau 30", "UPDATE('blue', '#1010FF')": "cập nhật khóa 'blue'", "LOOKUP('blue')": "tra khóa 'blue'", "INSERT(65)": "chèn 65", "JUSTIFY graph for campus links": "giải thích vì sao dùng đồ thị cho liên kết trong khuôn viên",
  };
  return notes[value] ?? value;
};

function buildTrace(kind: Section19VisualKind, scenario: string, n: number): Trace {
  switch (kind) {
    case "linear-search": return linearSearchTrace(scenario);
    case "binary-search": return binarySearchTrace(scenario);
    case "bubble-sort": return bubbleSortTrace(scenario);
    case "insertion-sort": return insertionSortTrace(scenario);
    case "stack-adt": return stackTrace(scenario);
    case "queue-adt": return queueTrace(scenario);
    case "linked-list": return linkedListTrace(scenario);
    case "binary-tree": return binaryTreeTrace(scenario);
    case "dictionary": return dictionaryTrace(scenario);
    case "adt-implementation": return adtImplementationTrace(scenario);
    case "complexity-comparator": return complexityComparison(scenario, n);
    case "recursion-trace": return recursionTrace(scenario);
    case "call-stack-unwinding": return callStackTrace(scenario);
  }
}

function Controls({ trace, index, setIndex, reset, locale }: { trace: Trace; index: number; setIndex: (index: number) => void; reset: () => void; locale: Locale }) {
  const jumpId = useId();
  return <div className={styles.controls}>
    <button type="button" data-s19-previous disabled={index === 0} onClick={() => setIndex(index - 1)}><ArrowLeft size={17} aria-hidden="true" />{locale === "vi" ? "Bước trước" : "Previous"}</button>
    <button type="button" data-s19-next aria-disabled={index === trace.steps.length - 1} onClick={() => { if (index < trace.steps.length - 1) setIndex(index + 1); }}>{locale === "vi" ? "Bước tiếp" : "Next"}<ArrowRight size={17} aria-hidden="true" /></button>
    <button type="button" data-s19-reset onClick={reset}><RotateCcw size={17} aria-hidden="true" />{locale === "vi" ? "Đặt lại" : "Reset"}</button>
    <label htmlFor={jumpId}><span>{locale === "vi" ? "Đi thẳng tới bước" : "Jump to step"}</span><select id={jumpId} data-s19-jump value={index} onChange={event => setIndex(Number(event.target.value))}>{trace.steps.map((item, itemIndex) => <option key={item.id} value={itemIndex}>{itemIndex + 1}. {local(item.title, locale)}</option>)}</select></label>
  </div>;
}

function ArrayCells({ values, stateFor, locale }: { values: readonly (number | string | null)[]; stateFor: (index: number) => string; locale: Locale }) {
  return <div className={styles.arrayStrip} role="region" tabIndex={0} aria-label={locale === "vi" ? "Dãy ô có thể cuộn ngang" : "Horizontally scrollable array cells"}>{values.map((value, index) => { const cellState = stateFor(index); return <div className={styles.arrayCell} key={index} data-index={index} data-state={cellState}><small>[{index}]</small><strong>{value ?? "∅"}</strong><span>{arrayStateLabel(cellState, locale)}</span></div>; })}</div>;
}
function SearchView({ kind, state, locale }: { kind: "linear-search" | "binary-search"; state: unknown; locale: Locale }) {
  if (kind === "linear-search") { const item = state as LinearSearchState; return <section className={styles.primary}><div className={styles.metricRow}><Metric label={locale === "vi" ? "Mục tiêu" : "Target"} value={item.target} /><Metric label={locale === "vi" ? "Số so sánh" : "Comparisons"} value={item.comparisons} /><Metric label={locale === "vi" ? "Kết quả" : "Result"} value={item.status === "found" ? `[${item.resultIndex}]` : item.status === "missing" ? "-1" : "—"} /></div><ArrayCells locale={locale} values={item.values} stateFor={index => index === item.currentIndex ? "active" : item.checkedIndices.includes(index) ? "checked" : "unvisited"} /><p className={styles.narration}>{item.currentIndex === null ? (locale === "vi" ? "Chưa có phép so sánh." : "No comparison yet.") : `${item.values[item.currentIndex]} ${item.values[item.currentIndex] === item.target ? "=" : "≠"} ${item.target}`}</p></section>; }
  const item = state as BinarySearchState; return <section className={styles.primary}><div className={styles.metricRow}><Metric label={locale === "vi" ? "Mục tiêu" : "Target"} value={item.target} /><Metric label={locale === "vi" ? "Cận dưới" : "Low"} value={item.low} /><Metric label={locale === "vi" ? "Điểm giữa" : "Mid"} value={item.middle ?? "—"} /><Metric label={locale === "vi" ? "Cận trên" : "High"} value={item.high} /><Metric label={locale === "vi" ? "So sánh" : "Comparisons"} value={item.comparisons} /></div><ArrayCells locale={locale} values={item.values} stateFor={index => index === item.middle ? "active" : item.discarded.includes(index) ? "discarded" : index >= item.low && index <= item.high ? "candidate" : "unvisited"} /><p className={styles.narration} data-error={item.status === "blocked-unsorted" || undefined}>{item.status === "blocked-unsorted" ? (locale === "vi" ? "Đã chặn: dữ liệu chưa sắp xếp nên tìm kiếm nhị phân không đáng tin cậy." : "Blocked: unsorted data makes binary search invalid.") : item.middle === null ? (locale === "vi" ? "Xác nhận dữ liệu tăng dần trước khi tính điểm giữa." : "Confirm ascending order before calculating the midpoint.") : `${item.comparedValue} ${item.decision === "equal" ? "=" : item.decision === "discard-left" ? "<" : ">"} ${item.target}`}</p></section>;
}
function SortView({ kind, state, locale }: { kind: "bubble-sort" | "insertion-sort"; state: unknown; locale: Locale }) {
  if (kind === "bubble-sort") { const item = state as BubbleSortState; return <section className={styles.primary}><div className={styles.metricRow}><Metric label={locale === "vi" ? "Lượt" : "Pass"} value={item.pass} /><Metric label={locale === "vi" ? "So sánh" : "Comparisons"} value={item.comparisons} /><Metric label={locale === "vi" ? "Đổi chỗ" : "Swaps"} value={item.swaps} /><Metric label={locale === "vi" ? "Đã đổi chỗ trong lượt" : "Swapped this pass"} value={yesNo(item.swappedThisPass, locale)} /></div><ArrayCells locale={locale} values={item.values} stateFor={index => item.pair?.includes(index) ? "active" : index >= item.completedFrom ? "complete" : "candidate"} /><p className={styles.narration}>{locale === "vi" ? "Biên đã hoàn tất chỉ mở rộng sau khi kết thúc trọn một lượt." : "The completed boundary grows only after a whole pass finishes."}</p></section>; }
  const item = state as InsertionSortState; return <section className={styles.primary}><div className={styles.keyTray}><span>{locale === "vi" ? "Khay lưu khóa" : "Saved key tray"}</span><strong>{item.key ?? "—"}</strong><small>{item.keyFrom === null ? "—" : `${locale === "vi" ? "từ" : "from"} [${item.keyFrom}]`}</small></div><div className={styles.metricRow}><Metric label={locale === "vi" ? "Đoạn đầu đã sắp xếp" : "Sorted prefix"} value={item.sortedEnd < 0 ? "∅" : `0..${item.sortedEnd}`} /><Metric label={locale === "vi" ? "Số lần dịch" : "Shifts"} value={item.shifts} /><Metric label={locale === "vi" ? "Vị trí chèn" : "Insert at"} value={item.insertionIndex ?? "—"} /></div><ArrayCells locale={locale} values={item.values} stateFor={index => item.compareIndex === index ? "active" : item.values[index] === null ? "gap" : index <= item.sortedEnd ? "complete" : "candidate"} /><p className={styles.narration}>{locale === "vi" ? "Khóa được lưu trước khi dịch; giá trị bằng nhau không bị dịch nên thứ tự được giữ ổn định." : "The key is saved before shifts; equality does not shift, so this fixture is stable."}</p></section>;
}
function Metric({ label, value }: { label: string; value: ReactNode }) { return <div className={styles.metric}><span>{label}</span><strong>{value}</strong></div>; }

function StackQueueView({ kind, state, locale, resetKey }: { kind: "stack-adt" | "queue-adt"; state: unknown; locale: Locale; resetKey: string }) {
  return kind === "stack-adt" ? <StackManual key={resetKey} initial={state as StackState} locale={locale} /> : <QueueManual key={resetKey} initial={state as QueueState} locale={locale} />;
}

type ManualEvent<T> = { operation: string; before: T; after: T; error: string | null };
function ManualSandboxDigest({ locale, operation, before, after, error, current }: { locale: Locale; operation: string; before: string; after: string; error: string | null; current: string }) {
  return <aside className={styles.manualSandbox} aria-live="polite">
    <strong>{locale === "vi" ? "Nhật ký khu thử thủ công" : "Manual sandbox log"}</strong>
    <p>{locale === "vi" ? "Khu thử này bắt đầu từ state của bước kịch bản phía trên; thao tác tại đây không thay đổi quy tắc hay Before/After của kịch bản." : "This sandbox starts from the scripted step state; actions here do not change the scripted rule or Before/After."}</p>
    <dl>
      <div><dt>{locale === "vi" ? "Thao tác thủ công" : "Manual operation"}</dt><dd>{operation}</dd></div>
      <div><dt>{locale === "vi" ? "Trước thao tác" : "Before operation"}</dt><dd>{before}</dd></div>
      <div><dt>{locale === "vi" ? "Sau thao tác" : "After operation"}</dt><dd>{after}</dd></div>
      <div><dt>{locale === "vi" ? "Lỗi" : "Error"}</dt><dd>{errorLabel(error, locale)}</dd></div>
      <div><dt>{locale === "vi" ? "State thủ công hiện tại" : "Current manual state"}</dt><dd>{current}</dd></div>
    </dl>
  </aside>;
}

const stackSnapshot = (state: StackState, locale: Locale) => locale === "vi"
  ? `top ${state.top}; kích thước ${state.size}/${state.capacity}; các ô [${state.cells.map(value => value ?? "∅").join(", ")}]; giá trị trả về ${state.returned ?? "—"}`
  : `top ${state.top}; size ${state.size}/${state.capacity}; cells [${state.cells.map(value => value ?? "∅").join(", ")}]; returned ${state.returned ?? "—"}`;
const queueSnapshot = (state: QueueState, locale: Locale) => locale === "vi"
  ? `front ${state.front}; rear ${state.rear}; số phần tử ${state.count}/${state.capacity}; thứ tự FIFO [${state.logicalOrder.join(", ") || "∅"}]; giá trị trả về ${state.returned ?? "—"}`
  : `front ${state.front}; rear ${state.rear}; count ${state.count}/${state.capacity}; FIFO order [${state.logicalOrder.join(", ") || "∅"}]; returned ${state.returned ?? "—"}`;

function StackManual({ initial, locale }: { initial: StackState; locale: Locale }) {
  const [manual, setManual] = useState(initial), [value, setValue] = useState("7"), [manualError, setManualError] = useState<string | null>(null), [event, setEvent] = useState<ManualEvent<StackState>>({ operation: locale === "vi" ? "Chưa có" : "None yet", before: initial, after: initial, error: null });
  useEffect(() => { setManual(initial); setManualError(null); setEvent({ operation: locale === "vi" ? "Chưa có" : "None yet", before: initial, after: initial, error: null }); }, [initial, locale]);
  const run = (op: "PUSH" | "POP" | "PEEK") => {
    const before = manual, operation = op === "PUSH" ? `${locale === "vi" ? "Thêm vào đỉnh" : "Push"} ${value} (PUSH)` : op === "POP" ? (locale === "vi" ? "Lấy khỏi đỉnh (POP)" : "Pop (POP)") : (locale === "vi" ? "Xem đỉnh (PEEK)" : "Peek (PEEK)");
    try { const after = applyStackOperation(before, op, op === "PUSH" ? Number(value) : undefined); setManual(after); setManualError(null); setEvent({ operation, before, after, error: after.error }); }
    catch (error) { const message = error instanceof Error ? error.message : String(error), localized = locale === "vi" && message === "PUSH requires a finite integer value" ? "PUSH cần một số nguyên hữu hạn." : message; setManualError(localized); setEvent({ operation, before, after: before, error: localized }); }
  };
  return <section className={styles.primary} aria-label={locale === "vi" ? "Khu thử ngăn xếp thủ công" : "Manual stack sandbox"}><div className={styles.stackView}>{[...manual.cells].reverse().map((cell, reverseIndex) => { const index = manual.capacity - 1 - reverseIndex; return <div key={index} data-index={index} data-state={index === manual.top ? "active" : cell === null ? "unvisited" : "complete"}><small>[{index}]</small><strong>{cell ?? "∅"}</strong>{index === manual.top && <span>← {locale === "vi" ? "đỉnh" : "top"}</span>}</div>; })}</div><div className={styles.metricRow}><Metric label={locale === "vi" ? "Đỉnh" : "Top"} value={manual.top} /><Metric label={locale === "vi" ? "Kích thước" : "Size"} value={manual.size} /><Metric label={locale === "vi" ? "Giá trị trả về" : "Return"} value={manual.returned ?? "—"} /><Metric label={locale === "vi" ? "Lỗi" : "Error"} value={errorLabel(manual.error, locale)} /></div><ManualControls locale={locale} value={value} setValue={setValue} actions={[{ id: "PUSH", label: locale === "vi" ? "Thêm (PUSH)" : "Push", run: () => run("PUSH") }, { id: "POP", label: locale === "vi" ? "Lấy (POP)" : "Pop", run: () => run("POP") }, { id: "PEEK", label: locale === "vi" ? "Xem đỉnh (PEEK)" : "Peek", run: () => run("PEEK") }]} error={manualError} /><ManualSandboxDigest locale={locale} operation={event.operation} before={stackSnapshot(event.before, locale)} after={stackSnapshot(event.after, locale)} error={event.error} current={stackSnapshot(manual, locale)} /></section>;
}
function QueueManual({ initial, locale }: { initial: QueueState; locale: Locale }) {
  const [manual, setManual] = useState(initial), [value, setValue] = useState("Z"), [manualError, setManualError] = useState<string | null>(null), [event, setEvent] = useState<ManualEvent<QueueState>>({ operation: locale === "vi" ? "Chưa có" : "None yet", before: initial, after: initial, error: null });
  useEffect(() => { setManual(initial); setManualError(null); setEvent({ operation: locale === "vi" ? "Chưa có" : "None yet", before: initial, after: initial, error: null }); }, [initial, locale]);
  const run = (op: "ENQUEUE" | "DEQUEUE") => {
    const before = manual, operation = op === "ENQUEUE" ? `${locale === "vi" ? "Thêm vào cuối" : "Enqueue"} ${value} (ENQUEUE)` : (locale === "vi" ? "Lấy ở đầu (DEQUEUE)" : "Dequeue (DEQUEUE)");
    try { const after = applyQueueOperation(before, op, op === "ENQUEUE" ? value : undefined); setManual(after); setManualError(null); setEvent({ operation, before, after, error: after.error }); }
    catch (error) { const message = error instanceof Error ? error.message : String(error), localized = locale === "vi" && message === "ENQUEUE requires a safe finite value" ? "ENQUEUE cần một giá trị hữu hạn hợp lệ." : message; setManualError(localized); setEvent({ operation, before, after: before, error: localized }); }
  };
  return <section className={styles.primary} aria-label={locale === "vi" ? "Khu thử hàng đợi thủ công" : "Manual queue sandbox"}><ArrayCells locale={locale} values={manual.cells} stateFor={index => index === manual.front && manual.count > 0 ? "active" : index === manual.rear ? "candidate" : manual.cells[index] === null ? "unvisited" : "complete"} /><div className={styles.metricRow}><Metric label={locale === "vi" ? "Front · vị trí lấy tiếp" : "Front · next removal"} value={manual.front} /><Metric label={locale === "vi" ? "Rear · vị trí chèn tiếp" : "Rear · next insertion"} value={manual.rear} /><Metric label={locale === "vi" ? "Số phần tử" : "Count"} value={manual.count} /><Metric label={locale === "vi" ? "Giá trị trả về" : "Return"} value={manual.returned ?? "—"} /></div><div className={styles.logicalOrder}><span>FIFO</span>{manual.logicalOrder.length ? manual.logicalOrder.map((item, index) => <strong key={index}>{item}</strong>) : <em>{locale === "vi" ? "rỗng" : "empty"}</em>}</div><ManualControls locale={locale} value={value} setValue={setValue} actions={[{ id: "ENQUEUE", label: locale === "vi" ? "Thêm (ENQUEUE)" : "Enqueue", run: () => run("ENQUEUE") }, { id: "DEQUEUE", label: locale === "vi" ? "Lấy (DEQUEUE)" : "Dequeue", run: () => run("DEQUEUE") }]} error={manualError} /><ManualSandboxDigest locale={locale} operation={event.operation} before={queueSnapshot(event.before, locale)} after={queueSnapshot(event.after, locale)} error={event.error} current={queueSnapshot(manual, locale)} /></section>;
}
function ManualControls({ locale, value, setValue, actions, error }: { locale: Locale; value: string; setValue: (value: string) => void; actions: Array<{ id: string; label: string; run: () => void }>; error: string | null }) { return <div className={styles.manual}><label>{locale === "vi" ? "Giá trị cho thao tác thủ công" : "Manual operation value"}<input value={value} onChange={event => setValue(event.target.value)} /></label><div>{actions.map(action => <button type="button" key={action.id} onClick={action.run}>{action.label}</button>)}</div>{error && <p data-error role="alert">{error}</p>}</div>; }

function LinkedListView({ state, locale }: { state: LinkedListState; locale: Locale }) {
  const byAddress = new Map(state.nodes.map(node => [node.address, node])), reachable = [], seen = new Set<number>(); let cursor = state.head;
  while (cursor !== -1 && !seen.has(cursor) && byAddress.has(cursor)) { const node = byAddress.get(cursor)!; reachable.push(node); seen.add(cursor); cursor = node.next; }
  const separate = state.nodes.filter(node => !seen.has(node.address));
  const nodeCard = (node: LinkedListState["nodes"][number]) => <article key={node.address} data-address={node.address} data-state={state.current === node.address ? "active" : seen.has(node.address) ? "complete" : "unvisited"}><small>@{node.address}</small><strong>{node.allocated ? node.data : locale === "vi" ? "ô tự do" : "free"}</strong><span>{locale === "vi" ? "Con trỏ next" : "Next pointer"}: {node.next === -1 ? "NULL" : node.next}</span></article>;
  return <section className={styles.primary}><div className={styles.metricRow}><Metric label="Head" value={state.head === -1 ? "NULL" : state.head} /><Metric label={locale === "vi" ? "Node trước" : "Previous"} value={state.previous === -1 ? "NULL" : state.previous} /><Metric label={locale === "vi" ? "Node hiện tại" : "Current"} value={state.current === -1 ? "NULL" : state.current} /><Metric label={locale === "vi" ? "Đi tới được từ head" : "Reachable from head"} value={reachable.map(node => node.address).join(" → ") || "∅"} /></div><div className={styles.pointerLanes}><div><strong>{locale === "vi" ? "Chuỗi con trỏ từ head" : "Pointer chain from head"}</strong><div className={styles.nodeRail}>{reachable.length ? reachable.flatMap((node, index) => [nodeCard(node), <span className={styles.pointerArrow} aria-hidden="true" key={`arrow-${node.address}`}>→</span>, ...(index === reachable.length - 1 ? [<strong className={styles.nullNode} key="null">NULL</strong>] : [])]) : <strong className={styles.nullNode}>HEAD → NULL</strong>}</div></div><div><strong>{locale === "vi" ? "Node ngoài chuỗi head" : "Nodes outside the head chain"}</strong><div className={styles.freeLane}>{separate.length ? separate.map(nodeCard) : <span>{locale === "vi" ? "Không có" : "None"}</span>}</div></div></div><p className={styles.narration}>{locale === "vi" ? "Mũi tên đi đúng theo trường next từ head đến NULL. Node tự do hoặc không reachable được tách riêng." : "Arrows follow the actual next field from head to NULL. Free or unreachable nodes are shown separately."}</p></section>;
}

function TreeView({ state, locale }: { state: BinaryTreeState; locale: Locale }) {
  const positions: Record<string, [number, number]> = { n50: [50, 12], n30: [28, 38], n70: [72, 38], n20: [16, 70], n40: [39, 70], n60: [61, 70], n80: [84, 70], n65: [67, 91] };
  return <section className={styles.primary}><figure className={styles.treeFigure}><svg viewBox="0 0 100 100" role="img" aria-labelledby="s19-tree-title s19-tree-desc"><title id="s19-tree-title">{locale === "vi" ? "Tìm và chèn trên cây tìm kiếm nhị phân" : "BST find and insert"}</title><desc id="s19-tree-desc">{locale === "vi" ? `Đường đi ${state.path.join(" → ") || "rỗng"}; trạng thái ${term(state.status, locale)}.` : `Path ${state.path.join(" → ") || "empty"}; status ${state.status}.`}</desc>{state.nodes.flatMap(node => (["left", "right"] as const).map(side => { const child = node[side]; if (!child || !positions[node.id] || !positions[child]) return null; return <line key={`${node.id}-${child}`} x1={positions[node.id][0]} y1={positions[node.id][1]} x2={positions[child][0]} y2={positions[child][1]} data-state={state.path.includes(node.id) && state.path.includes(child) ? "active" : "default"} />; }))}{state.nodes.map(node => { const [x, y] = positions[node.id] ?? [50, 50]; return <g key={node.id} data-node-id={node.id} data-state={state.currentId === node.id ? "active" : state.path.includes(node.id) ? "complete" : "unvisited"}><circle cx={x} cy={y} r="7" /><text x={x} y={y + 1.5}>{node.value}</text></g>; })}</svg><figcaption>{locale === "vi" ? "Đường đi theo quy tắc giá trị bên trái < node < giá trị bên phải; giá trị trùng bị từ chối." : "The path follows left < node < right; duplicates are rejected."}</figcaption></figure><div className={styles.metricRow}><Metric label={locale === "vi" ? "Node gốc" : "Root"} value={state.root ?? "NULL"} /><Metric label={locale === "vi" ? "Đường đi" : "Path"} value={state.path.join(" → ") || "∅"} /><Metric label={locale === "vi" ? "Quyết định" : "Decision"} value={term(state.decision, locale)} /><Metric label={locale === "vi" ? "Trạng thái" : "Status"} value={term(state.status, locale)} /></div></section>;
}

function DictionaryView({ state, locale }: { state: DictionaryState; locale: Locale }) { const operation = locale === "vi" ? state.operation === "lookup" ? "TRA KHÓA" : state.operation === "insert" ? "CHÈN" : "CẬP NHẬT" : state.operation.toUpperCase(); return <section className={styles.primary}><div className={styles.interfaceCard}><span>{locale === "vi" ? "Thao tác ADT bên ngoài" : "External ADT operation"}</span><strong>{operation}({state.key}{state.argument ? `, ${state.argument}` : ""})</strong><small>{term(state.status, locale)} · {locale === "vi" ? "trả về" : "return"} {state.returned ?? "—"}</small></div><div className={styles.entryGrid}>{state.entries.map((entry, index) => <article key={entry.key} data-index={index} data-state={state.scannedKeys.includes(entry.key) ? "active" : "unvisited"}><small>{locale === "vi" ? "Vị trí nội bộ" : "Internal position"} {index}</small><strong>{entry.key}</strong><span>{entry.value}</span></article>)}</div><p className={styles.narration}>{locale === "vi" ? "Khóa là định danh duy nhất; vị trí trong mảng chỉ là chi tiết của cách cài đặt." : "A key is the unique identifier; the array position is only an implementation detail."}</p></section>; }

function ADTView({ state, locale }: { state: ADTImplementationState; locale: Locale }) { return <section className={styles.primary}><div className={styles.adtLanes}><article><span>{locale === "vi" ? "Giao diện bên ngoài" : "External interface"}</span><strong>{modelText(state.externalADT, locale)}</strong><code>{adtOperationText(state.externalOperation, locale)}</code><p>{modelText(state.observableResult, locale)}</p></article><ArrowRight aria-hidden="true" /><article><span>{locale === "vi" ? "Cách biểu diễn bên trong" : "Internal representation"}</span><strong>{modelText(state.representation, locale)}</strong><ol>{state.internalSteps.map((item, index) => <li key={item} data-state={index < state.revealedSteps.length ? "complete" : "unvisited"}>{modelText(item, locale)}</li>)}</ol></article></div><aside className={styles.invariant}><strong>{locale === "vi" ? "Bất biến cần giữ" : "Invariant"}</strong><p>{modelText(state.invariant, locale)}</p><small>{modelText(state.edgeCase, locale)} · {modelText(state.costNote, locale)}</small></aside><aside className={styles.graphBoundary}><strong>{locale === "vi" ? "Phạm vi ADT đồ thị" : "Graph ADT scope"}</strong><p>{modelText(state.graphBoundary.vocabulary, locale)}</p><p>{modelText(state.graphBoundary.suitability, locale)}</p><small>{modelText(state.graphBoundary.excluded, locale)}</small></aside></section>; }

function ComplexityView({ state, locale }: { state: ComplexityState; locale: Locale }) {
  const auxiliarySpaceChart = state.metric.startsWith("auxiliary storage"), maxN = Math.max(...state.chart.map(point => point.n)), maxValue = Math.max(1, ...state.chart.flatMap(point => point.values)); const sx = (n: number) => 12 + (n / maxN) * 78, sy = (value: number) => 86 - (value / maxValue) * 68;
  const chartMetric = auxiliarySpaceChart ? (locale === "vi" ? "đơn vị bộ nhớ phụ trợ" : "auxiliary storage units") : (locale === "vi" ? "số thao tác minh họa" : "operation count");
  return <section className={styles.primary}><div className={styles.assumptions}><strong>{modelText(state.task, locale)}</strong><span>n={state.n}</span><ul>{state.assumptions.map(item => <li key={item}>{modelText(item, locale)}</li>)}</ul><small>{modelText(state.metric, locale)}</small></div><figure className={styles.growthFigure}><svg viewBox="0 0 100 100" role="img" aria-labelledby="s19-growth-title s19-growth-desc"><title id="s19-growth-title">{locale === "vi" ? `Biểu đồ ${chartMetric} theo n` : auxiliarySpaceChart ? "Auxiliary storage units by n" : "Teaching operation count by n"}</title><desc id="s19-growth-desc">{state.rows.map(row => `${modelText(row.label, locale)}: ${auxiliarySpaceChart ? `${row.spaceBigO}, ${row.exactSpace ?? "—"} ${chartMetric}` : `${complexityClassText(row.timeBigO, locale)}, ${row.exactTime ?? "—"} ${chartMetric}`}`).join("; ")}</desc><defs><marker id="s19-axis-arrow" markerWidth="5" markerHeight="5" refX="4" refY="2.5" orient="auto"><path d="M0,0 L5,2.5 L0,5 z" /></marker></defs><line className={styles.axis} x1="10" y1="88" x2="95" y2="88" markerEnd="url(#s19-axis-arrow)" /><line className={styles.axis} x1="10" y1="88" x2="10" y2="7" markerEnd="url(#s19-axis-arrow)" />{state.chart.map(point => <g key={point.n}><line className={styles.tick} x1={sx(point.n)} y1="86" x2={sx(point.n)} y2="90" /><text x={sx(point.n)} y="95">{point.n}</text></g>)}{state.rows.map((row, rowIndex) => <g key={row.label} data-line-pattern={row.pattern}><polyline points={state.chart.map(point => `${sx(point.n)},${sy(point.values[rowIndex])}`).join(" ")} />{state.chart.map(point => <circle key={`${row.label}-${point.n}`} cx={sx(point.n)} cy={sy(point.values[rowIndex])} r="1.6" />)}<text x={sx(maxN)} y={Math.max(8, sy(state.chart.at(-1)!.values[rowIndex]) - 2)}>{modelText(row.label, locale)}</text></g>)}<text x="77" y="99">{locale === "vi" ? "kích thước đầu vào n" : "input size n"}</text><text x="12" y="5">{chartMetric}</text></svg><figcaption>{locale === "vi" ? `Mỗi đường có nhãn và kiểu nét riêng; trục dọc biểu diễn ${chartMetric}. Thời lượng hoạt ảnh không phải bằng chứng.` : `Curves use labels and distinct patterns; the vertical axis shows ${chartMetric}. Animation duration is not evidence.`}</figcaption></figure><div className={styles.tableWrap} role="region" tabIndex={0} aria-label={locale === "vi" ? "Bảng thời gian và bộ nhớ phụ trợ" : "Time and space table"}><table><caption>{locale === "vi" ? "So sánh thời gian và bộ nhớ phụ trợ cho cùng tác vụ, kích thước đầu vào và giả định" : "Time and auxiliary-space comparison under the same task, input size and assumptions"}</caption><thead><tr><th>{locale === "vi" ? "Mô hình" : "Model"}</th><th>{auxiliarySpaceChart ? (locale === "vi" ? "Số đơn vị bộ nhớ phụ trợ" : "Exact auxiliary storage units") : (locale === "vi" ? "Số thao tác minh họa" : "Exact teaching count")}</th><th>{locale === "vi" ? "Thời gian" : "Time"}</th><th>{locale === "vi" ? "Bộ nhớ phụ trợ" : "Auxiliary space"}</th></tr></thead><tbody>{state.rows.map(row => <tr key={row.label}><th scope="row">{modelText(row.label, locale)}</th><td>{(auxiliarySpaceChart ? row.exactSpace : row.exactTime) ?? "—"}</td><td>{complexityClassText(row.timeBigO, locale)}</td><td>{row.spaceBigO}</td></tr>)}</tbody></table></div></section>;
}

function RecursionView({ state, locale }: { state: RecursionState; locale: Locale }) {
  const argument = (value: string) => locale === "vi" ? value.replace("remaining", "còn lại") : value;
  const error = locale === "vi" ? state.errorCode === "NO_PROGRESS_TOWARD_BASE_CASE" ? "Không tiến gần base case" : state.errorCode === "BASE_CASE_UNREACHABLE" ? "Không thể tới base case" : null : state.errorCode;
  const repair = locale === "vi" ? state.errorCode === "NO_PROGRESS_TOWARD_BASE_CASE" ? "Gọi F(n - 1), không gọi lại F(n), và giữ một base case có thể tới được." : state.errorCode === "BASE_CASE_UNREACHABLE" ? "Đưa đối số tiến về n = 0 thay vì đi xa nó." : null : state.repair;
  return <section className={styles.primary}><div className={styles.recursionGrid}><article><span>{locale === "vi" ? "Lời gọi hiện tại" : "Active call"}</span><strong>{state.activeCall?.id ?? "—"}</strong><small>{state.activeCall ? argument(state.activeCall.argument) : term(state.status, locale)}</small></article><article><span>{locale === "vi" ? "Thứ tự gọi" : "Call order"}</span><ol>{state.callOrder.map(call => <li key={call.id}>{call.id} · {locale === "vi" ? "độ sâu" : "depth"} {call.depth}{call.base ? ` · ${locale === "vi" ? "base case" : "base"}` : ""}</li>)}</ol></article><article><span>{locale === "vi" ? "Thứ tự trả về" : "Return order"}</span><ol>{state.returnOrder.map(item => <li key={item.id}>{item.id} → {item.returned}</li>)}</ol></article></div>{state.status === "blocked-invalid" && <aside className={styles.blocked} data-error={state.errorCode}><strong>{error}</strong><p>{repair}</p><small>{locale === "vi" ? "Số lời gọi đã chạy: 0" : "Executed calls: 0"}</small></aside>}<div className={styles.metricRow}><Metric label={locale === "vi" ? "Độ sâu lớn nhất" : "Max depth"} value={state.maxDepth} /><Metric label={locale === "vi" ? "Số lời gọi đã chạy" : "Executed calls"} value={state.executedCalls} /><Metric label={locale === "vi" ? "Kết quả" : "Result"} value={state.result ?? "—"} /></div></section>;
}

function CallStackView({ state, locale }: { state: CallStackState; locale: Locale }) {
  const direction = state.phase === "push" ? (locale === "vi" ? "Thêm frame ↓" : "Push call ↓") : state.phase === "base-return" || state.phase === "unwind" || state.phase === "complete" ? (locale === "vi" ? "Trả về / tháo stack ↑" : "Return / unwind ↑") : (locale === "vi" ? "Sẵn sàng" : "Ready");
  return <section className={styles.primary}><div className={styles.stackPanels}><article><h3>{locale === "vi" ? "Cây lời gọi" : "Call tree"}</h3><ul>{state.callTree.map(edge => <li key={edge.child}>{edge.parent ?? (locale === "vi" ? "GỐC" : "ROOT")} → {edge.child}</li>)}</ul></article><article><h3>{locale === "vi" ? "Ngăn xếp lời gọi đang hoạt động" : "Live call stack"}</h3><div className={styles.frames}>{[...state.frames].reverse().map((frame, index) => <div key={frame.frameId} data-frame-id={frame.frameId} data-state={index === 0 ? "active" : "complete"}><strong>{frame.function}({frame.argument})</strong><span>{locale === "vi" ? "Biến cục bộ" : "Locals"}: {Object.keys(frame.locals).length ? Object.entries(frame.locals).map(([key, value]) => `${key === "childResult" && locale === "vi" ? "kết quả từ lời gọi con" : key}=${value}`).join(", ") : locale === "vi" ? "chưa có" : "none"}</span><small>{locale === "vi" ? `Điểm tiếp tục: ${frame.resumePoint}` : frame.resumePoint}</small></div>)}</div></article><article><h3>{locale === "vi" ? "Biểu thức trả về" : "Returned expression"}</h3><strong className={styles.expression}>{state.outputExpression}</strong><p>{state.poppedFrameId ? `${locale === "vi" ? "Đã lấy frame khỏi stack" : "Popped frame"}: ${state.poppedFrameId}` : "—"}</p></article></div><div className={styles.metricRow}><Metric label={locale === "vi" ? "Hướng di chuyển" : "Direction"} value={direction} /><Metric label={locale === "vi" ? "Frame trên cùng" : "Top frame"} value={state.topFrameId ?? "∅"} /><Metric label={locale === "vi" ? "Kết quả từ lời gọi con" : "Child result"} value={state.childResultReceived ?? "—"} /><Metric label={locale === "vi" ? "Giá trị trả về" : "Returned"} value={state.returned ?? "—"} /></div></section>;
}

function PrimaryView({ kind, state, locale, resetKey }: { kind: Section19VisualKind; state: unknown; locale: Locale; resetKey: string }) {
  if (kind === "linear-search" || kind === "binary-search") return <SearchView kind={kind} state={state} locale={locale} />;
  if (kind === "bubble-sort" || kind === "insertion-sort") return <SortView kind={kind} state={state} locale={locale} />;
  if (kind === "stack-adt" || kind === "queue-adt") return <StackQueueView kind={kind} state={state} locale={locale} resetKey={resetKey} />;
  if (kind === "linked-list") return <LinkedListView state={state as LinkedListState} locale={locale} />;
  if (kind === "binary-tree") return <TreeView state={state as BinaryTreeState} locale={locale} />;
  if (kind === "dictionary") return <DictionaryView state={state as DictionaryState} locale={locale} />;
  if (kind === "adt-implementation") return <ADTView state={state as ADTImplementationState} locale={locale} />;
  if (kind === "complexity-comparator") return <ComplexityView state={state as ComplexityState} locale={locale} />;
  if (kind === "recursion-trace") return <RecursionView state={state as RecursionState} locale={locale} />;
  return <CallStackView state={state as CallStackState} locale={locale} />;
}

type DigestItem = { label: string; value: ReactNode };
function stateDigest(kind: Section19VisualKind, state: unknown, locale: Locale): DigestItem[] {
  const t = (vi: string, en: string) => locale === "vi" ? vi : en, pointer = (value: number) => value === -1 ? "NULL" : value;
  switch (kind) {
    case "linear-search": { const item = state as LinearSearchState; return [{ label: t("Dãy", "Values"), value: `[${item.values.join(", ")}]` }, { label: t("Vị trí đang xét", "Current index"), value: item.currentIndex ?? "—" }, { label: t("Số so sánh", "Comparisons"), value: item.comparisons }, { label: t("Trạng thái", "Status"), value: term(item.status, locale) }]; }
    case "binary-search": { const item = state as BinarySearchState; return [{ label: t("Khoảng ứng viên", "Candidate interval"), value: item.low <= item.high ? `[${item.low}..${item.high}]` : "∅" }, { label: t("Điểm giữa", "Midpoint"), value: item.middle ?? "—" }, { label: t("Quyết định", "Decision"), value: term(item.decision, locale) }, { label: t("Trạng thái", "Status"), value: term(item.status, locale) }]; }
    case "bubble-sort": { const item = state as BubbleSortState; return [{ label: t("Dãy", "Values"), value: `[${item.values.join(", ")}]` }, { label: t("Cặp đang xét", "Active pair"), value: item.pair?.join(" ↔ ") ?? "—" }, { label: t("So sánh / đổi chỗ", "Comparisons / swaps"), value: `${item.comparisons} / ${item.swaps}` }, { label: t("Quyết định", "Decision"), value: term(item.decision, locale) }]; }
    case "insertion-sort": { const item = state as InsertionSortState; return [{ label: t("Dãy", "Values"), value: `[${item.values.map(value => value ?? "∅").join(", ")}]` }, { label: t("Khóa đã lưu", "Saved key"), value: item.key ?? "—" }, { label: t("Vị trí so sánh", "Compare index"), value: item.compareIndex ?? "—" }, { label: t("Quyết định", "Decision"), value: term(item.decision, locale) }]; }
    case "stack-adt": { const item = state as StackState; return [{ label: t("Thao tác kịch bản", "Scripted operation"), value: item.operation === "—" ? t("chưa có", "none") : item.operation }, { label: t("Các ô", "Cells"), value: `[${item.cells.map(value => value ?? "∅").join(", ")}]` }, { label: t("Đỉnh / kích thước", "Top / size"), value: `${item.top} / ${item.size}` }, { label: t("Giá trị trả về", "Returned value"), value: item.returned ?? "—" }, { label: t("Trạng thái / lỗi", "Status / error"), value: `${term(item.status, locale)} / ${errorLabel(item.error, locale)}` }]; }
    case "queue-adt": { const item = state as QueueState; return [{ label: t("Thao tác kịch bản", "Scripted operation"), value: item.operation === "—" ? t("chưa có", "none") : item.operation }, { label: t("Thứ tự FIFO", "FIFO order"), value: `[${item.logicalOrder.join(", ") || "∅"}]` }, { label: "front / rear / count", value: `${item.front} / ${item.rear} / ${item.count}` }, { label: t("Kết quả / lỗi", "Return / error"), value: `${item.returned ?? "—"} / ${errorLabel(item.error, locale)}` }]; }
    case "linked-list": { const item = state as LinkedListState; return [{ label: "head / current / previous", value: `${pointer(item.head)} / ${pointer(item.current)} / ${pointer(item.previous)}` }, { label: t("Đường đã duyệt", "Traversal path"), value: item.path.join(" → ") || "∅" }, { label: t("Chuỗi reachable", "Reachable chain"), value: item.reachable.join(" → ") || "∅" }, { label: t("Các node và con trỏ next", "Nodes and next pointers"), value: item.nodes.map(node => `@${node.address}:${node.allocated ? node.data : t("tự do", "free")}→${pointer(node.next)}`).join("; ") }, { label: t("Trạng thái", "Status"), value: term(item.status, locale) }]; }
    case "binary-tree": { const item = state as BinaryTreeState; return [{ label: t("Node gốc", "Root"), value: item.root ?? "NULL" }, { label: t("Đường đi", "Path"), value: item.path.join(" → ") || "∅" }, { label: t("Các node và child", "Nodes and children"), value: item.nodes.map(node => `${node.id}:${node.value}(${node.left ?? "NULL"},${node.right ?? "NULL"})`).join("; ") || "∅" }, { label: t("Quyết định", "Decision"), value: term(item.decision, locale) }, { label: t("Trạng thái", "Status"), value: term(item.status, locale) }]; }
    case "dictionary": { const item = state as DictionaryState; return [{ label: t("Yêu cầu", "Request"), value: `${term(item.operation, locale)} “${item.key}”${item.argument ? ` = ${item.argument}` : ""}` }, { label: t("Các khóa đã quét", "Scanned keys"), value: item.scannedKeys.join(" → ") || "∅" }, { label: t("Các entry", "Entries"), value: item.entries.map(entry => `${entry.key}=${entry.value}`).join("; ") || "∅" }, { label: t("Giá trị trả về", "Returned value"), value: item.returned ?? "—" }, { label: t("Trạng thái", "Status"), value: term(item.status, locale) }]; }
    case "adt-implementation": { const item = state as ADTImplementationState; return [{ label: t("ADT và thao tác", "ADT and operation"), value: `${modelText(item.externalADT, locale)} · ${adtOperationText(item.externalOperation, locale)}` }, { label: t("Cách biểu diễn", "Representation"), value: modelText(item.representation, locale) }, { label: t("Số bước đã mở", "Revealed steps"), value: `${item.revealedSteps.length}/${item.internalSteps.length}` }, { label: t("Bước vừa mở", "Latest revealed step"), value: item.revealedSteps.length ? modelText(item.revealedSteps.at(-1)!, locale) : "—" }, { label: t("Trạng thái", "Status"), value: term(item.status, locale) }]; }
    case "complexity-comparator": { const item = state as ComplexityState, space = item.metric.startsWith("auxiliary storage"); return [{ label: t("Tác vụ", "Task"), value: modelText(item.task, locale) }, { label: t("Kích thước đầu vào", "Input size"), value: item.n }, { label: t("Metric biểu đồ", "Chart metric"), value: space ? t("đơn vị bộ nhớ phụ trợ", "auxiliary storage units") : t("số thao tác minh họa", "teaching operation count") }, { label: t("Trạng thái", "Status"), value: term(item.status, locale) }]; }
    case "recursion-trace": { const item = state as RecursionState; return [{ label: t("Lời gọi hiện tại", "Active call"), value: item.activeCall?.id ?? "—" }, { label: t("Số lời gọi / độ sâu lớn nhất", "Calls / max depth"), value: `${item.executedCalls} / ${item.maxDepth}` }, { label: t("Kết quả", "Result"), value: item.result ?? "—" }, { label: t("Trạng thái", "Status"), value: term(item.status, locale) }]; }
    case "call-stack-unwinding": { const item = state as CallStackState; return [{ label: t("Các frame đang hoạt động", "Live frames"), value: item.frames.map(frame => frame.frameId).join(" → ") || "∅" }, { label: t("Frame trên cùng", "Top frame"), value: item.topFrameId ?? "∅" }, { label: t("Biểu thức trả về", "Returned expression"), value: item.outputExpression }, { label: t("Giai đoạn", "Phase"), value: term(item.phase, locale) }]; }
  }
}

function StateDigest({ kind, state, locale, hook }: { kind: Section19VisualKind; state: unknown; locale: Locale; hook: "before" | "after" }) {
  return <dl className={styles.stateDigest} {...(hook === "before" ? { "data-state-before": true } : { "data-state-after": true })}>{stateDigest(kind, state, locale).map(item => <div key={item.label}><dt>{item.label}</dt><dd>{item.value}</dd></div>)}</dl>;
}

function SemanticFallback({ trace, locale, index }: { trace: Trace; locale: Locale; index: number }) { return <details className={styles.fallback} data-s19-fallback data-state-fallback><summary>{locale === "vi" ? "Đọc state đầy đủ, bảng dấu vết và mã giả" : "Read complete state, trace table and pseudocode"}</summary><div className={styles.tableWrap} role="region" tabIndex={0} aria-label={locale === "vi" ? "Bảng dấu vết đầy đủ" : "Semantic trace table"}><table><caption>{local(trace.convention, locale)}</caption><thead><tr><th>{locale === "vi" ? "Bước" : "Step"}</th><th>{locale === "vi" ? "Sự kiện" : "Event"}</th><th>{locale === "vi" ? "Dòng đang chạy" : "Active line"}</th><th>{locale === "vi" ? "Trước" : "Before"}</th><th>{locale === "vi" ? "Sau" : "After"}</th><th>{locale === "vi" ? "Kết quả" : "Outcome"}</th></tr></thead><tbody>{trace.steps.map((item, itemIndex) => <tr key={item.id} data-s19-fallback-step={item.id} data-fallback-step={item.id} aria-current={itemIndex === index ? "step" : undefined}><th scope="row">{itemIndex + 1}. {local(item.title, locale)}</th><td>{item.event}</td><td><code>{item.activeRule}<br />{item.codeLine}</code></td><td><code data-state-before>{JSON.stringify(item.before)}</code></td><td><code data-state-after>{JSON.stringify(item.after)}</code></td><td>{local(item.outcome, locale)}</td></tr>)}</tbody></table></div><ol className={styles.pseudocode}>{trace.pseudocode.map((line, lineIndex) => <li key={`${line}-${lineIndex}`}><code>{line}</code></li>)}</ol></details>; }

export function Section19ComputationalWorkbench({ kind, locale }: { readonly kind: Section19VisualKind; readonly locale: Locale }) {
  const canonical = scenarioIds[kind][0], [scenario, setScenario] = useState(canonical), [index, setIndex] = useState(0), [n, setN] = useState(8); const trace = useMemo(() => buildTrace(kind, scenario, n), [kind, scenario, n]); const current = trace.steps[Math.min(index, trace.steps.length - 1)];
  useEffect(() => { if (!scenarioIds[kind].includes(scenario)) { setScenario(scenarioIds[kind][0]); setIndex(0); } }, [kind, scenario]);
  const reset = () => { setScenario(canonical); setN(8); setIndex(0); };
  const state = current.after as { status?: string; error?: string | null; result?: number | null };
  const result = state.error ? "error" : state.status ?? (index === trace.steps.length - 1 ? "complete" : "pending");
  return <div className={styles.workbench} role="region" aria-label={local(workbenchNames[kind], locale)} data-visual-kind={kind} data-scenario={scenario} data-result={result}>
    <div className={styles.setup}><label>{locale === "vi" ? "Kịch bản đã duyệt" : "Reviewed scenario"}<select data-s19-scenario value={scenario} onChange={event => { setScenario(event.target.value); setIndex(0); }}>{scenarioIds[kind].map(id => <option key={id} value={id}>{human(id, locale)}</option>)}</select></label>{kind === "complexity-comparator" && <label>{locale === "vi" ? "Kích thước n" : "Input size n"}<select value={n} onChange={event => { setN(Number(event.target.value)); setIndex(0); }}>{[1, 5, 8, 16, 32].map(value => <option key={value}>{value}</option>)}</select></label>}<div className={styles.convention}><strong>{locale === "vi" ? "Quy ước khóa" : "Locked convention"}</strong><span>{local(trace.convention, locale)}</span></div></div>
    <Controls trace={trace} index={index} setIndex={setIndex} reset={reset} locale={locale} />
    <section className={styles.stepCard} data-s19-step={current.id}><header><span>{locale === "vi" ? "Bước" : "Step"} {index + 1}/{trace.steps.length}</span><h3>{local(current.title, locale)}</h3></header><div className={styles.ruleGrid} data-s19-rule><div><span>{locale === "vi" ? "Quy tắc hiện tại" : "Current rule"}</span><strong>{local(current.rule, locale)}</strong></div><div><span>{locale === "vi" ? "Dòng đang chạy" : "Active pseudocode"}</span><code>{current.activeRule} · {current.codeLine}</code></div></div><div className={styles.explanation}><p><strong>{locale === "vi" ? "Hành động" : "Action"}:</strong> {local(current.action, locale)}</p><p><strong>{locale === "vi" ? "Vì sao" : "Why"}:</strong> {local(current.why, locale)}</p><p data-s19-outcome><strong>{locale === "vi" ? "Kết quả" : "Outcome"}:</strong> {local(current.outcome, locale)}</p></div></section>
    <div className={styles.status} role="status" aria-live="polite">{locale === "vi" ? `Đang hiển thị bước ${index + 1}: ${local(current.title, locale)}.` : `Showing step ${index + 1}: ${local(current.title, locale)}.`}</div>
    <PrimaryView kind={kind} state={current.after} locale={locale} resetKey={`${scenario}-${index}`} />
    <section className={styles.beforeAfter} data-s19-state aria-label={locale === "vi" ? "Tóm tắt trạng thái trước và sau" : "Before and after state summary"}><article role="region" tabIndex={0} aria-label={locale === "vi" ? "Trạng thái trước bước hiện tại" : "State before the current step"}><span>{locale === "vi" ? "Trước bước" : "Before"}</span><StateDigest kind={kind} state={current.before} locale={locale} hook="before" /></article><ArrowRight aria-hidden="true" /><article role="region" tabIndex={0} aria-label={locale === "vi" ? "Trạng thái sau bước hiện tại" : "State after the current step"}><span>{locale === "vi" ? "Sau bước" : "After"}</span><StateDigest kind={kind} state={current.after} locale={locale} hook="after" /></article></section>
    <SemanticFallback trace={trace} locale={locale} index={index} />
  </div>;
}
